--- a/apps/ios/YunleFunTests/NativeGameRuntimeTests.swift
+++ b/apps/ios/YunleFunTests/NativeGameRuntimeTests.swift
@@ -1571,6 +1571,233 @@
 /// Diagnostic phase stamps only. The original N10 benchmark and product flow stay unchanged.
 @MainActor
 final class NativeGameStartupPhaseLiveTests: XCTestCase {
+    // Independent mechanism experiment; this block does not alter the original v3 trace or N10.
+    private static let blankProbeLogger = Logger(subsystem: "fun.yunle.apps.tests", category: "native-game-blank-probe")
+
+    func testHeldBlankPageStartupPhaseForGomoku() async throws {
+        guard #available(iOS 17, *), NativeGameHostEnvironment.previewOrigin != nil,
+              ProcessInfo.processInfo.environment["YUNLEFUN_PLAY_PREVIEW"] == "1",
+              ProcessInfo.processInfo.environment["YUNLEFUN_NATIVE_GAME_BLANK_PROBE"] == "1" else {
+            throw XCTSkip("Held-blank diagnostics require their explicit opt-in and the fixed preview")
+        }
+        let fixture = try await NativeGameRuntimeFixture(simulated: false)
+        fixture.root.collectResourceTiming = true
+        let cache = NativeGameResourceCache(defaults: fixture.defaults)
+        addTeardownBlock {
+            await MainActor.run { cache.cancel() }
+            for id in await fixture.trackedProfiles() { await cache.clear(profileID: id) }
+            await fixture.close()
+        }
+        let game = try fixture.game("gomoku"), mode = try fixture.mode("computer", gameID: "gomoku")
+        let profile = try fixture.runtime.gameResourceProfile(for: game, catalog: fixture.catalog)
+        fixture.track(profile)
+        await fixture.endAll()
+        await cache.clear(profileID: profile)
+        let preparationStart = ProcessInfo.processInfo.systemUptime
+        cache.download(manifestURL: try XCTUnwrap(game.resourceManifestURL.flatMap(URL.init(string:))),
+                       gameID: game.gameId, profileID: profile, wifiOnly: false)
+        try await fixture.wait(seconds: 180) { !cache.isBusy }
+        let entry = try XCTUnwrap(cache.entry(gameID: game.gameId, profileID: profile), cache.error ?? "Missing preparation")
+        guard let resourceVersion = game.resourceVersion, entry.version == resourceVersion else {
+            throw failure("Held-blank experiment requires the current verified resource version")
+        }
+        let preparationEnd = ProcessInfo.processInfo.systemUptime
+        let order = [("normal", 1), ("heldBlank", 1), ("heldBlank", 2), ("normal", 2), ("normal", 3), ("heldBlank", 3)]
+        _ = Self.blankProbeLogger
+        var rows: [[String: Any]] = []
+        var completed = false
+        defer {
+            attach(["kind": "gomoku-held-blank-mechanism-n3", "completed": completed, "results": rows,
+                    "origin": "http://127.0.0.1:18146", "expectedSamples": 6, "samplesPerCondition": 3,
+                    "order": order.map { ["condition": $0.0, "pair": $0.1] as [String: Any] },
+                    "resourcePreparation": ["beginUptime": preparationStart, "endUptime": preparationEnd,
+                                            "durationMilliseconds": (preparationEnd - preparationStart) * 1000,
+                                            "version": entry.version, "preparedOnceSharedAcrossCases": true],
+                    "UIKitAnimationsEnabledDuringFixture": UIView.areAnimationsEnabled,
+                    "normalDefinition": "normal-without-additional-blank; not OS cold or independently reset WebKit",
+                    "scope": "Isolated guest fixture only; a public-API blank-page mechanism experiment after explicit resource preparation. No product adoption or hidden gameplay.",
+                    "limits": ["Preparation is common and reported once; HTTP caches are not cleared or re-downloaded between alternating cases",
+                               "WebKit/JIT/network process state can carry over across cases; this small mechanism probe is not a 30 percent target result",
+                               "Profile/cleanup checks are experimental guards, not verification of real account-generation races",
+                               "Public SDK does not guarantee that a held blank view shares a WebContent process with the fresh game",
+                               "Warm creation/wait and full start-to-genuine-ready costs use native uptime; no document/server clock subtraction",
+                               "Weak WK object release is not proof of process termination, RSS release or exclusive game memory"]], name: "native-gomoku-held-blank-mechanism")
+        }
+        for (index, item) in order.enumerated() {
+            await fixture.endAll()
+            rows.append(try await blankCase(fixture, game: game, mode: mode, expectedProfile: profile,
+                                            iteration: index + 1, condition: item.0, pair: item.1))
+        }
+        completed = true
+    }
+
+    @available(iOS 17, *)
+    private func blankCase(_ fixture: NativeGameRuntimeFixture, game: NativeGame, mode: NativeGameMode,
+                           expectedProfile: UUID, iteration: Int, condition: String, pair: Int) async throws -> [String: Any] {
+        let owner = BlankViewOwner(fixture: fixture, game: game, expectedProfile: expectedProfile)
+        addTeardownBlock { await MainActor.run { owner.close(reason: "fixture-teardown") } }
+        let hostPID = ProcessInfo.processInfo.processIdentifier
+        let started = ProcessInfo.processInfo.systemUptime
+        var completed = false
+        var details: [String: Any] = [:]
+        Self.blankProbeLogger.notice("YUNLEFUN_BLANK_PROBE_BEGIN iteration=\(iteration, privacy: .public) hostPID=\(hostPID, privacy: .public) condition=\(condition, privacy: .public) uptimeSeconds=\(started, privacy: .public)")
+        defer {
+            owner.close(reason: "case-defer")
+            let ended = ProcessInfo.processInfo.systemUptime
+            Self.blankProbeLogger.notice("YUNLEFUN_BLANK_PROBE_END iteration=\(iteration, privacy: .public) hostPID=\(hostPID, privacy: .public) condition=\(condition, privacy: .public) uptimeSeconds=\(ended, privacy: .public)")
+            if !completed {
+                attach(["iteration": iteration, "condition": condition, "pair": pair, "completed": false,
+                        "caseBeginUptime": started, "caseEndUptime": ended, "blank": owner.diagnostics,
+                        "details": details], name: "native-gomoku-held-blank-partial-\(iteration)")
+            }
+        }
+        return try await withTaskCancellationHandler {
+            owner.startMonitoring()
+            try owner.validate()
+            if condition == "heldBlank" { details["blankReadyProof"] = try await owner.initializeBlank() }
+            try owner.validate(requireHeld: condition == "heldBlank")
+            let result = try await trace(fixture, game: game, mode: mode, expectedProfile: expectedProfile)
+            details["trace"] = result
+            try owner.validate(requireHeld: condition == "heldBlank")
+            let points = try XCTUnwrap(result["points"] as? [[String: Any]])
+            let readyPoint = try XCTUnwrap(points.first { $0["phase"] as? String == "on-game-ready-received" })
+            let readyUptime = try XCTUnwrap(readyPoint["uptimeSeconds"] as? NSNumber).doubleValue
+            let heldThroughReady = condition == "heldBlank" && owner.isHoldingView
+            owner.close(reason: "sample-ended")
+            let weakReleased = await owner.waitForWeakRelease()
+            try Task.checkCancellation()
+            completed = true
+            return ["iteration": iteration, "condition": condition, "pair": pair, "completed": true,
+                    "hostPID": Int(hostPID), "caseBeginUptime": started, "genuineReadyUptime": readyUptime,
+                    "caseStartToGenuineReadyMilliseconds": (readyUptime - started) * 1000,
+                    "blankHeldThroughReady": heldThroughReady, "blank": owner.diagnostics,
+                    "weakBlankObjectReleasedWithinBound": condition == "heldBlank" ? weakReleased as Any : NSNull(),
+                    "blankReadyProof": details["blankReadyProof"] ?? NSNull(), "trace": result]
+        } onCancel: {
+            Task { @MainActor in owner.invalidate(reason: "task-cancelled") }
+        }
+    }
+
+    @available(iOS 17, *)
+    @MainActor
+    private final class BlankViewOwner {
+        private weak var fixture: NativeGameRuntimeFixture?
+        private let game: NativeGame
+        private let expectedProfile: UUID
+        private var view: WKWebView?
+        private weak var releasedView: WKWebView?
+        private var monitor: Task<Void, Never>?
+        private var memoryObserver: NSObjectProtocol?
+        private var invalidation: String?
+        private var closeReason: String?
+        private var createdAt: TimeInterval?
+        private var readyAt: TimeInterval?
+        private var releasedAt: TimeInterval?
+        private var validationCount = 0
+
+        init(fixture: NativeGameRuntimeFixture, game: NativeGame, expectedProfile: UUID) {
+            self.fixture = fixture; self.game = game; self.expectedProfile = expectedProfile
+        }
+        var isHoldingView: Bool { view != nil }
+        var diagnostics: [String: Any] {
+            ["viewCreated": createdAt != nil, "creationBeginUptime": createdAt.map { $0 as Any } ?? NSNull(),
+             "blankReadyUptime": readyAt.map { $0 as Any } ?? NSNull(), "releasedUptime": releasedAt.map { $0 as Any } ?? NSNull(),
+             "initializationMilliseconds": createdAt.flatMap { start in readyAt.map { ($0 - start) * 1000 } }.map { $0 as Any } ?? NSNull(),
+             "heldAfterReadyMilliseconds": readyAt.flatMap { start in releasedAt.map { ($0 - start) * 1000 } }.map { $0 as Any } ?? NSNull(),
+             "profileValidationCount": validationCount, "profileMonitorMilliseconds": 100,
+             "invalidationReason": invalidation.map { $0 as Any } ?? NSNull(), "closeReason": closeReason.map { $0 as Any } ?? NSNull()]
+        }
+        func startMonitoring() {
+            memoryObserver = NotificationCenter.default.addObserver(
+                forName: UIApplication.didReceiveMemoryWarningNotification, object: nil, queue: .main) { [weak self] _ in
+                    Task { @MainActor in self?.invalidate(reason: "memory-warning") }
+                }
+            monitor = Task { @MainActor [weak self] in
+                while !Task.isCancelled {
+                    guard let self else { return }
+                    do { try self.validate() } catch { self.invalidate(reason: "profile-or-cleanup-changed"); return }
+                    do { try await Task.sleep(nanoseconds: 100_000_000) } catch { return }
+                }
+            }
+        }
+        func validate(requireHeld: Bool = false) throws {
+            try Task.checkCancellation()
+            guard invalidation == nil, let fixture, !fixture.runtime.isIdentityCleanupPending else {
+                close(reason: "invalidated-or-cleanup")
+                throw NSError(domain: "NativeBlankProbe", code: 1, userInfo: [NSLocalizedDescriptionKey: "Blank probe boundary is no longer valid"])
+            }
+            let current = try fixture.runtime.gameResourceProfile(for: game, catalog: fixture.catalog)
+            fixture.track(current)
+            validationCount += 1
+            guard current == expectedProfile, !requireHeld || view != nil else {
+                invalidate(reason: "profile-or-held-view-changed")
+                throw NSError(domain: "NativeBlankProbe", code: 2, userInfo: [NSLocalizedDescriptionKey: "Blank probe profile or held view changed"])
+            }
+        }
+        func initializeBlank() async throws -> [String: Any] {
+            try validate()
+            guard view == nil else { throw NSError(domain: "NativeBlankProbe", code: 3) }
+            createdAt = ProcessInfo.processInfo.systemUptime
+            let configuration = WKWebViewConfiguration()
+            configuration.websiteDataStore = WKWebsiteDataStore(forIdentifier: expectedProfile)
+            configuration.userContentController = WKUserContentController()
+            configuration.mediaTypesRequiringUserActionForPlayback = .all
+            configuration.preferences.javaScriptCanOpenWindowsAutomatically = false
+            let blank = WKWebView(frame: .zero, configuration: configuration)
+            view = blank
+            let title = "blank-probe-" + UUID().uuidString
+            blank.loadHTMLString("""
+                <!doctype html><html><head><meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'none'; connect-src 'none'; img-src 'none'; style-src 'none'; font-src 'none'; media-src 'none'; object-src 'none'; base-uri 'none'; form-action 'none'"><title>\(title)</title></head><body></body></html>
+                """, baseURL: nil)
+            let deadline = ProcessInfo.processInfo.systemUptime + 8
+            while ProcessInfo.processInfo.systemUptime < deadline {
+                try validate(requireHeld: true)
+                let value = try await NativeGameEntryProbe.evaluate(blank, script: """
+                    return {ready: document.readyState === 'complete', expectedTitle: document.title === expectedTitle,
+                            aboutBlank: location.href === 'about:blank', resourceEntries: performance.getEntriesByType('resource').length,
+                            hasHostBridge: typeof window.ylf !== 'undefined'};
+                    """, arguments: ["expectedTitle": title])
+                try validate(requireHeld: true)
+                if let proof = value as? [String: Any], proof["ready"] as? Bool == true,
+                   proof["expectedTitle"] as? Bool == true, proof["aboutBlank"] as? Bool == true,
+                   (proof["resourceEntries"] as? NSNumber)?.intValue == 0, proof["hasHostBridge"] as? Bool == false {
+                    guard blank.configuration.websiteDataStore.identifier == expectedProfile,
+                          blank.configuration.userContentController.userScripts.isEmpty else {
+                        throw NSError(domain: "NativeBlankProbe", code: 4)
+                    }
+                    readyAt = ProcessInfo.processInfo.systemUptime
+                    return proof
+                }
+                try await Task.sleep(nanoseconds: 50_000_000)
+            }
+            throw URLError(.timedOut)
+        }
+        func invalidate(reason: String) {
+            if invalidation == nil { invalidation = reason }
+            close(reason: reason)
+        }
+        func close(reason: String) {
+            monitor?.cancel(); monitor = nil
+            if let memoryObserver { NotificationCenter.default.removeObserver(memoryObserver) }
+            memoryObserver = nil
+            if let view {
+                releasedView = view
+                view.stopLoading(); view.navigationDelegate = nil; view.uiDelegate = nil
+                self.view = nil
+                releasedAt = ProcessInfo.processInfo.systemUptime
+            }
+            if closeReason == nil { closeReason = reason }
+        }
+        func waitForWeakRelease() async -> Bool {
+            let deadline = ProcessInfo.processInfo.systemUptime + 1
+            while releasedView != nil && ProcessInfo.processInfo.systemUptime < deadline {
+                do { try await Task.sleep(nanoseconds: 50_000_000) } catch { break }
+            }
+            return releasedView == nil
+        }
+    }
+    // End independent held-blank mechanism experiment.
+
     func testPreparedStartupPhaseTraceForTwoGames() async throws {
         guard #available(iOS 17, *),
               NativeGameHostEnvironment.previewOrigin != nil,
